def total(nums: list[int]) -> int:
    return sum(nums)


print(total([1, 2, 3]))
try:
    total("123")
except TypeError as exc:
    print("运行时：", exc)

def find(uid: int) -> str | None:
    return {1: "Ada"}.get(uid)


name = find(2)
try:
    print(name.upper())
except AttributeError as exc:
    print("运行时：", type(exc).__name__)

